def transform(grid):
    h, w = len(grid), len(grid[0])
    r0 = next(r for r, row in enumerate(grid) if all(v == 3 for v in row))
    c0 = next(c for c in range(w) if all(grid[r][c] == 3 for r in range(h)))
    return [
        [3 if grid[r][c] == 3 else (4 if max(abs(r - r0), abs(c - c0)) % 2 == 0 else 0)
         for c in range(w)]
        for r in range(h)
    ]
